@Test
void oppositeItemOrdersCompleteWithinTwoSeconds() {
    inventory.register(10L, 10);
    inventory.register(22L, 10);

    var start = new CountDownLatch(1);
    var pool = Executors.newFixedThreadPool(2);

    try {
        var first = pool.submit(() -> {
            start.await();
            orderService.createOrder(1L, List.of(
                    new OrderItem(10L, 1), new OrderItem(22L, 2)));
            return null;
        });
        var second = pool.submit(() -> {
            start.await();
            orderService.createOrder(2L, List.of(
                    new OrderItem(22L, 1), new OrderItem(10L, 1)));
            return null;
        });

        assertTimeoutPreemptively(Duration.ofSeconds(2), () -> {
            start.countDown();
            first.get();
            second.get();
        });

        assertEquals(8, inventory.countOf(10L));
        assertEquals(7, inventory.countOf(22L));
    } finally {
        pool.shutdownNow();
    }
}
